import{_ as a,o,a as t,aw as n}from"./chunks/framework.JerLf5Kq.js";const h=JSON.parse('{"title":"Hexagonal Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md"}'),r={name:"guide/architecture.md"};function i(s,e,c,l,d,p){return o(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="hexagonal-architecture" tabindex="-1">Hexagonal Architecture <a class="header-anchor" href="#hexagonal-architecture" aria-label="Permalink to &quot;Hexagonal Architecture&quot;">​</a></h1><p>The Supernova backend (<code>apps/api</code>) strictly follows <strong>Alistair Cockburn&#39;s Hexagonal Architecture</strong> (Ports and Adapters pattern).</p><h2 id="dependency-rule" tabindex="-1">Dependency Rule <a class="header-anchor" href="#dependency-rule" aria-label="Permalink to &quot;Dependency Rule&quot;">​</a></h2><p>Dependencies always point inwards toward the core domain:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ Inbound Adapters ]             [ Core Application ]            [ Outbound Adapters ]</span></span>
<span class="line"><span>  HTTP Handler        -----&gt;     in.Service (Port)     -----&gt;     MitosisAuthor (Port)</span></span>
<span class="line"><span>  (net/http Mux)                 Job State Machine                LLM Client Adapter</span></span>
<span class="line"><span>                                 Repair Loop                      (packages/mitosis-author)</span></span>
<span class="line"><span>                                 Worker Pool</span></span>
<span class="line"><span>                                                       -----&gt;     MitosisCompiler (Port)</span></span>
<span class="line"><span>                                                                  CLI Subprocess Adapter</span></span>
<span class="line"><span>                                                                  (packages/mitosis-compiler)</span></span>
<span class="line"><span>                                                       -----&gt;     JobStore (Port)</span></span>
<span class="line"><span>                                                                  In-Memory / SQLite Store</span></span>
<span class="line"><span>                                                       -----&gt;     ArtifactPublisher (Port)</span></span>
<span class="line"><span>                                                                  Download ZIP Publisher</span></span>
<span class="line"><span>                                                                  GitHub PR Publisher</span></span></code></pre></div><h3 id="core-domain-internal-core-domain" tabindex="-1">Core Domain (<code>internal/core/domain/</code>) <a class="header-anchor" href="#core-domain-internal-core-domain" aria-label="Permalink to &quot;Core Domain (\`internal/core/domain/\`)&quot;">​</a></h3><ul><li>Contains pure entity models: <code>Job</code>, <code>FigmaComponentSpec</code>, <code>CompiledArtifact</code>, <code>Framework</code>, and domain error sentinels.</li><li>Contains pure utility functions like <code>NormalizeComponentName</code> without I/O or system side effects.</li><li>Zero dependencies on external frameworks, HTTP routers, or database drivers.</li></ul><h3 id="inbound-ports-internal-core-port-in" tabindex="-1">Inbound Ports (<code>internal/core/port/in/</code>) <a class="header-anchor" href="#inbound-ports-internal-core-port-in" aria-label="Permalink to &quot;Inbound Ports (\`internal/core/port/in/\`)&quot;">​</a></h3><ul><li><code>Service</code>: Defines the primary use cases: <ul><li><code>SubmitExtraction(ctx, req) (jobID, error)</code></li><li><code>GetJob(ctx, jobID) (*domain.Job, error)</code></li><li><code>GetDownloadZip(ctx, jobID) ([]byte, error)</code></li></ul></li></ul><h3 id="outbound-ports-internal-core-port-out" tabindex="-1">Outbound Ports (<code>internal/core/port/out/</code>) <a class="header-anchor" href="#outbound-ports-internal-core-port-out" aria-label="Permalink to &quot;Outbound Ports (\`internal/core/port/out/\`)&quot;">​</a></h3><ul><li><code>MitosisAuthor</code>: Abstraction for authoring <code>.lite.tsx</code> components.</li><li><code>MitosisCompiler</code>: Abstraction for compiling to framework targets.</li><li><code>JobStore</code>: Abstraction for persisting jobs and artifact payloads.</li><li><code>ArtifactPublisher</code>: Abstraction for delivering artifacts (ZIP bundle, GitHub PR).</li></ul><h3 id="automatic-repair-loop" tabindex="-1">Automatic Repair Loop <a class="header-anchor" href="#automatic-repair-loop" aria-label="Permalink to &quot;Automatic Repair Loop&quot;">​</a></h3><p>If the compiler reports syntax or semantic errors in generated Mitosis code:</p><ol><li>Attempt 0: LLM generates initial <code>.lite.tsx</code>.</li><li>Compiler parses and compiles to target frameworks.</li><li>If errors are detected and <code>attempts &lt; maxRetries</code>: <ul><li>Errors are captured and passed into the LLM prompt under <code>CRITICAL REPAIR REQUIRED:</code>.</li><li>LLM corrects the source code addressing the specific compiler messages.</li></ul></li><li>If compilation passes: Component is marked <code>done</code> and artifacts are stored.</li><li>If retries are exhausted: Component is marked <code>failed</code> with stage and error details, and the job continues processing remaining components.</li></ol>`,14)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
